public class E207 {
    int v = 0;
    static void mutate(E207 o) { o.v = 100; }
    static void reassign(E207 o) { o = new E207(); o.v = 999; }
    static void swap(int a, int b) { int t = a; a = b; b = t; }
    public static void main(String[] args) {
        E207 x = new E207();
        mutate(x);
        System.out.println("after mutate: " + x.v);
        reassign(x);
        System.out.println("after reassign: " + x.v);
        int a = 1, b = 2;
        swap(a, b);
        System.out.println("after swap: " + a + "," + b);
    }
}
